import{_ as a,o as l,c as t,aw as o}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Continuous Integration","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/common2/ci-cd/main/continuous-integration.md","filePath":"wiki/dev-commit/common2/ci-cd/main/continuous-integration.md"}'),n={name:"wiki/dev-commit/common2/ci-cd/main/continuous-integration.md"};function e(r,i,u,s,c,d){return l(),t("div",null,[...i[0]||(i[0]=[o('<h1 id="continuous-integration" tabindex="-1">Continuous Integration <a class="header-anchor" href="#continuous-integration" aria-label="Permalink to &quot;Continuous Integration&quot;">​</a></h1><ul><li><strong>Continuous Integration, CI (непрерывная интеграция)</strong> - практика разработки программного обеспечения, которая заключается в постоянном слиянии рабочих копий в общую основную ветвь разработки (до нескольких раз в день) и выполнении частых автоматизированных сборок проекта для скорейшего выявления потенциальных дефектов и решения интеграционных проблем</li><li>В обычном проекте, где над разными частями системы разработчики трудятся независимо, стадия интеграции является заключительной. Она может непредсказуемо задержать окончание работ. Переход к непрерывной интеграции позволяет снизить трудоёмкость интеграции и сделать её более предсказуемой за счёт наиболее раннего обнаружения и устранения ошибок и противоречий, но основным преимуществом является сокращение стоимости исправления дефекта, за счёт раннего его выявления</li><li><strong>Continuous Integration System (CIS)</strong> - системы непрерывной интеграции применяются для автоматизации интеграционного тестирования</li><li>Автоматические интеграционные тесты выполняются сразу же после внесения изменений, что позволяет обнаруживать и устранять ошибки в короткие сроки</li></ul><h3 id="задачи-службы" tabindex="-1">Задачи службы <a class="header-anchor" href="#задачи-службы" aria-label="Permalink to &quot;Задачи службы&quot;">​</a></h3><ol><li>Получение исходного кода из репозитория</li><li>Сборка проекта</li><li>Выполнение тестов</li><li>Развёртывание готового проекта</li><li>Отправка отчетов</li></ol><h3 id="сборка" tabindex="-1">Сборка <a class="header-anchor" href="#сборка" aria-label="Permalink to &quot;Сборка&quot;">​</a></h3><ul><li>Сборки по расписанию (Daily Build - ежедневная сборка) как правило, проводятся в нерабочее время, ночью (Nightly Build), планируются таким образом, чтобы к началу очередного рабочего дня были готовы результаты тестирования</li><li>Для различия дополнительно вводится система нумерации сборок — обычно, каждая сборка нумеруется натуральным числом, которое увеличивается с каждой новой сборкой. Исходные тексты и другие исходные данные при взятии их из репозитория системы контроля версий помечаются номером сборки. Благодаря этому, точно такая же сборка может быть точно воспроизведена в будущем — достаточно взять исходные данные по нужной метке и запустить процесс снова. Это даёт возможность повторно выпускать даже очень старые версии программы с небольшими исправлениями</li></ul><h3 id="плюсы" tabindex="-1">Плюсы <a class="header-anchor" href="#плюсы" aria-label="Permalink to &quot;Плюсы&quot;">​</a></h3><ul><li>проблемы интеграции выявляются и исправляются быстро, что оказывается дешевле</li><li>немедленный прогон модульных тестов для свежих изменений</li><li>постоянное наличие текущей стабильной версии вместе с продуктами сборок — для тестирования, демонстрации</li><li>немедленный эффект от неполного или неработающего кода приучает разработчиков к работе в итеративном режиме с более коротким циклом</li></ul><h3 id="минусы" tabindex="-1">Минусы <a class="header-anchor" href="#минусы" aria-label="Permalink to &quot;Минусы&quot;">​</a></h3><ul><li>значительные затраты на поддержку работы непрерывной интеграции</li><li>необходимость в дополнительных вычислительных ресурсах под нужды непрерывной интеграции</li></ul><h3 id="принцип-деиствия" tabindex="-1">Принцип действия <a class="header-anchor" href="#принцип-деиствия" aria-label="Permalink to &quot;Принцип действия&quot;">​</a></h3><ol><li>CIS производит мониторинг системы контроля версий</li><li>При изменении исходных кодов в репозитории производится обновление локального хранилища</li><li>Выполняются необходимые проверки и модульные тесты</li><li>Исходные коды компилируются в готовые выполняемые модули</li><li>Выполняются тесты интеграционного уровня</li><li>Генерируется отчет о тестировании</li></ol>',12)])])}const _=a(n,[["render",e]]);export{m as __pageData,_ as default};
